import React,{useState}from'react';import{createRoot}from'react-dom/client';import'./styles.css';
const initial=[['Research proposal','BIO 204 · Dr. Kim','Tomorrow','High',72],['Problem set 06','MATH 118 · Prof. Shah','Thu, 17 Oct','Medium',35],['Reading reflection','HIST 102 · Dr. Ellis','Mon, 21 Oct','Low',0],['Group presentation','DES 210 · Team project','Wed, 23 Oct','High',90]];
function App(){const[tasks,setTasks]=useState(initial),[filter,setFilter]=useState('All tasks'),[add,setAdd]=useState(false);let list=tasks.filter(x=>filter==='All tasks'||x[3]===filter);return <main><header><div className="brand"><span className="logo">✓</span><div><b>Duewell</b><small>Assignment planner</small></div></div><button className="avatar">AJ</button></header><section className="hero"><div><p className="eyebrow">MONDAY, 14 OCTOBER</p><h1>Make space for<br/><em>what matters.</em></h1><p className="muted">You have 4 tasks this week. You’re on track.</p></div><button className="primary" onClick={()=>setAdd(true)}>＋ Add task</button></section><div className="summary"><div><b>3</b><span>due this week</span></div><div><b>62%</b><span>week completed</span></div><div><b>1</b><span>needs attention</span></div></div><div className="toolbar"><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Filter priorities"><option>All tasks</option><option>High</option><option>Medium</option><option>Low</option></select><button className="filter active">Upcoming</button><button className="filter">Calendar</button></div><section className="card tasks"><div className="sectiontitle"><h2>Upcoming work</h2><span>October 14–20</span></div>{list.map((x,i)=><div className="task" key={x[0]}><button className={'check '+(x[4]===100?'done':'')} onClick={()=>setTasks(tasks.map(t=>t[0]===x[0]?[...t,100]:t))} aria-label={'Mark '+x[0]+' complete'}>{x[4]===100?'✓':''}</button><div className="taskbody"><h3>{x[0]}</h3><p>{x[1]}</p><div className="taskmeta"><span className={'priority '+x[3].toLowerCase()}>{x[3]} priority</span><span>◷ {x[2]}</span></div><div className="progress"><i style={{width:x[4]+'%'}}/></div></div><button className="more">•••</button></div>)}</section>{add&&<div className="modal"><div className="modalbox"><button className="close" onClick={()=>setAdd(false)}>×</button><span className="eyebrow">NEW TASK</span><h2>What needs doing?</h2><input placeholder="Task title" autoFocus/><input placeholder="Course or project"/><input type="date"/><button className="primary full" onClick={()=>{setAdd(false);setTasks([['New assignment','New course','Friday','Medium',0],...tasks])}}>Add to planner</button></div></div>}</main>}createRoot(document.getElementById('root')).render(<App/>);
